import { chromium } from '@playwright/test';
const b = await chromium.launch(); const p = await b.newPage();
const fails=[]; p.on('response', r => { if (r.status()>=400) fails.push(r.status()+' '+r.url()); });
for (const pg of ['index','products','pricing','orders','about','contact']) {
  await p.goto(`http://127.0.0.1:${process.env.PORT}/${pg}.html`); await p.evaluate(()=>document.fonts.ready);
  console.log(pg, await p.evaluate(()=>document.fonts.check("16px 'Acme Sans'") && [...document.fonts].map(f=>f.status).join()));
}
console.log('failed requests:', fails); await b.close();
EOF
